# Generated by Trae Work
"""
Kimi AI 高级功能模块：
1. 角色命名 - 给每条轨道取有角色感的名字（参考乐器名+功能，避免冲突）
2. 歌曲结构分析 - 识别段落（前奏/主歌/副歌等）
3. 镜头脚本 - 基于结构和活跃度生成镜头时间线
4. 字幕提示 - 关键节点的引导文字

所有功能都有本地缓存，避免重复调用 API。
"""

import json
import os
import hashlib
import urllib.request
from typing import Dict, List, Optional, Any

from .config import get_kimi_api_key
from .logger import get_logger
from .kimi_translate import KIMI_API_URL, REQUEST_TIMEOUT, CACHE_DIR
from .kimi_prompts import (
    K3_MODEL, K3_REASONING_EFFORT,
    NAMING_CACHE_FILE, GROUPING_CACHE_FILE, SCRIPT_CACHE_FILE,
    NAMING_SYSTEM_PROMPT, GROUPING_SYSTEM_PROMPT, SCRIPT_SYSTEM_PROMPT,
)

logger = get_logger(__name__)


class KimiAIService:
    """Kimi AI 高级功能服务：角色命名、轨道分组、歌曲分析+镜头脚本。"""

    def __init__(self, api_key: Optional[str] = None):
        self._api_key = api_key

    # ============== 内部工具 ==============

    def _load_cache(self, cache_file: str) -> Dict:
        if os.path.exists(cache_file):
            try:
                with open(cache_file, "r", encoding="utf-8") as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return {}
        return {}

    def _save_cache(self, cache: Dict, cache_file: str) -> None:
        os.makedirs(os.path.dirname(cache_file), exist_ok=True)
        try:
            with open(cache_file, "w", encoding="utf-8") as f:
                json.dump(cache, f, ensure_ascii=False, indent=2)
        except IOError as e:
            logger.warning("Failed to save Kimi AI cache: %s", e)

    @staticmethod
    def _hash_track_info(tracks_info: List[Dict]) -> str:
        key = json.dumps(tracks_info, ensure_ascii=False, sort_keys=True)
        return hashlib.md5(key.encode('utf-8')).hexdigest()[:16]

    def _call_api(self, system_prompt: str, user_msg: str) -> Any:
        """通用 Kimi API 调用，返回解析后的 JSON。K3 优先，失败回退 K2.6。"""
        api_key = get_kimi_api_key(self._api_key)

        models = [
            {"name": K3_MODEL, "reasoning": K3_REASONING_EFFORT, "max_tokens": 12000, "timeout": 180},
            {"name": "kimi-k2.6", "reasoning": None, "max_tokens": 8000, "timeout": 120},
        ]

        for cfg in models:
            payload_dict = {
                "model": cfg["name"],
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_msg},
                ],
                "max_tokens": cfg["max_tokens"],
            }
            if cfg["reasoning"]:
                payload_dict["reasoning_effort"] = cfg["reasoning"]

            payload = json.dumps(payload_dict).encode("utf-8")

            req = urllib.request.Request(
                KIMI_API_URL,
                data=payload,
                headers={
                    "Content-Type": "application/json",
                    "Authorization": f"Bearer {api_key}",
                },
                method="POST",
            )

            try:
                logger.info("Trying Kimi AI model: %s", cfg['name'])
                with urllib.request.urlopen(req, timeout=cfg["timeout"]) as resp:
                    body = resp.read().decode("utf-8")
                    data = json.loads(body)
                    if "choices" not in data or not data["choices"]:
                        logger.warning("Kimi AI %s returned empty choices: %s", cfg['name'], body[:200])
                        continue
                    content = data["choices"][0]["message"]["content"]
                    content = content.strip()
                    if content.startswith("```"):
                        content = content.strip("`")
                        if content.lower().startswith("json"):
                            content = content[4:]
                        content = content.strip()
                    result = json.loads(content)
                    logger.info("Kimi AI %s succeeded", cfg['name'])
                    return result
            except Exception as e:
                logger.warning("Kimi AI %s failed: %s", cfg['name'], e)
                continue

        logger.error("All Kimi AI models failed")
        return None

    # ============== 1. 角色命名 ==============

    def name_tracks(self, tracks_info: List[Dict[str, Any]]) -> Dict[int, Dict]:
        """调用 Kimi 为每条轨道取角色名。

        Args:
            tracks_info: 轨道信息列表，每项包含 id, instrument_name, layer_name,
                         group, note_count, density, inst_index
        Returns:
            {track_id: {"name": str, "group": str}} 字典
        """
        if not tracks_info:
            return {}

        cache_key = self._hash_track_info(tracks_info)
        cache = self._load_cache(NAMING_CACHE_FILE)
        if cache_key in cache:
            return {int(k): v for k, v in cache[cache_key].items()}

        lines = []
        for t in tracks_info:
            group_cn = {"melody": "旋律", "harmony": "和声", "bass": "低音", "rhythm": "节奏"}.get(t["group"], t["group"])
            lines.append(
                f"- ID{t['id']}: 乐器={t['instrument_name']}, "
                f"原层名={t['layer_name']}, "
                f"声部={group_cn}, "
                f"音符数={t['note_count']}, "
                f"密度={t['density']:.1f}/秒, "
                f"同乐器第{t['inst_index']}个"
            )

        user_msg = "请为以下每条轨道取一个角色名（格式：角色+乐器，2-5字，不与乐器名重复，同乐器不同层用功能区分）：\n" + "\n".join(lines)

        result = self._call_api(NAMING_SYSTEM_PROMPT, user_msg)

        if not result:
            return {t["id"]: {"name": f"{t['instrument_name']}{t['inst_index'] if t['inst_index'] > 1 else ''}", "group": t["group"]} for t in tracks_info}

        naming = {}
        try:
            for item in result:
                naming[int(item["id"])] = {
                    "name": item["name"],
                    "group": item.get("group", "melody"),
                }
        except (KeyError, TypeError, ValueError):
            return {t["id"]: {"name": f"{t['instrument_name']}{t['inst_index'] if t['inst_index'] > 1 else ''}", "group": t["group"]} for t in tracks_info}

        cache[cache_key] = {str(k): v for k, v in naming.items()}
        self._save_cache(cache, NAMING_CACHE_FILE)
        return naming

    # ============== 1.5. 轨道分组 ==============

    def group_tracks(self, tracks_info: List[Dict[str, Any]],
                     naming_results: Dict[int, Dict]) -> Dict[str, Any]:
        """调用 Kimi 将轨道分成 1-8 个组。

        Args:
            tracks_info: 原始轨道信息列表
            naming_results: name_tracks 的返回结果 {id: {name, group}}
        Returns:
            {groups: [{index, name, track_ids, order, visual_style}]}
        """
        if not tracks_info or not naming_results:
            return self._grouping_fallback(tracks_info)

        cache_input = []
        for t in tracks_info:
            nr = naming_results.get(t["id"], {})
            cache_input.append({
                "id": t["id"],
                "name": nr.get("name", ""),
                "instrument": t["instrument_name"],
                "group": t["group"],
                "note_count": t["note_count"],
                "density": round(t["density"], 1),
            })
        cache_key = self._hash_track_info(cache_input)
        cache = self._load_cache(GROUPING_CACHE_FILE)
        if cache_key in cache:
            return cache[cache_key]

        lines = []
        for t in tracks_info:
            nr = naming_results.get(t["id"], {})
            group_cn = {"melody": "旋律", "harmony": "和声", "bass": "低音", "rhythm": "节奏"}.get(t["group"], t["group"])
            lines.append(
                f"- ID{t['id']}: 角色={nr.get('name', '?')}, "
                f"乐器={t['instrument_name']}, "
                f"声部={group_cn}, "
                f"音符数={t['note_count']}, "
                f"密度={t['density']:.1f}/秒"
            )

        user_msg = "请将以下轨道分成 1-8 个组，按组间重要性和组内重要性排序：\n" + "\n".join(lines)

        result = self._call_api(GROUPING_SYSTEM_PROMPT, user_msg)

        if not result or "groups" not in result:
            return self._grouping_fallback(tracks_info)

        all_ids = set(t["id"] for t in tracks_info)
        assigned = set()
        for g in result["groups"]:
            for tid in g.get("track_ids", []):
                assigned.add(tid)
        if all_ids != assigned:
            logger.warning("Group validation failed: unassigned=%s, extra=%s, using fallback",
                           all_ids - assigned, assigned - all_ids)
            return self._grouping_fallback(tracks_info)

        if len(result["groups"]) > 8:
            result["groups"].sort(key=lambda g: g["index"])
            while len(result["groups"]) > 8:
                smallest = result["groups"].pop()
                result["groups"][-1]["track_ids"].extend(smallest["track_ids"])
                result["groups"][-1]["order"].extend(smallest["order"])

        for i, g in enumerate(result["groups"]):
            g["index"] = i

        cache[cache_key] = result
        self._save_cache(cache, GROUPING_CACHE_FILE)
        return result

    def _grouping_fallback(self, tracks_info: List[Dict]) -> Dict[str, Any]:
        """分组回退：按原始声部组分组。"""
        group_map: Dict[str, list] = {}
        for t in tracks_info:
            g = t.get("group", "melody")
            if g not in group_map:
                group_map[g] = []
            group_map[g].append(t["id"])

        group_order = ["melody", "harmony", "bass", "rhythm", "fx"]
        sorted_groups = [g for g in group_order if g in group_map]
        groups = []
        for i, g in enumerate(sorted_groups):
            ids = group_map[g]
            name_map = {"melody": "主旋组", "harmony": "和声组", "bass": "贝斯组", "rhythm": "节奏组", "fx": "效果组"}
            groups.append({
                "index": i,
                "name": name_map.get(g, g),
                "track_ids": ids,
                "order": ids,
                "visual_style": "cool" if g in ("melody", "harmony") else "warm",
            })
        return {"groups": groups}

    # ============== 2. 歌曲分析+镜头脚本 ==============

    def analyze_song(self, tracks: List[Dict], total_seconds: float,
                     activity_summary: List[Dict]) -> Dict[str, Any]:
        """调用 Kimi 分析歌曲结构并生成镜头脚本。

        Args:
            tracks: 轨道信息列表（含 id, name, instrument, group, note_count）
            total_seconds: 歌曲总时长
            activity_summary: 活跃度摘要
        Returns:
            {sections, cameras, danmaku, subtitles} 字典
        """
        cache_key_input = {
            "tracks": [{"id": t["id"], "name": t["name"], "group": t["group"]} for t in tracks],
            "total": round(total_seconds, 1),
            "activity_len": len(activity_summary),
        }
        cache_key = self._hash_track_info([{**cache_key_input, "activity": str(len(activity_summary))}])
        cache = self._load_cache(SCRIPT_CACHE_FILE)
        if cache_key in cache:
            return cache[cache_key]

        step = max(1, len(activity_summary) // 60)
        compressed = []
        for i in range(0, len(activity_summary), step):
            point = activity_summary[i]
            compressed.append({
                "t": round(point["time"], 1),
                "m": round(point.get("melody", 0), 2),
                "h": round(point.get("harmony", 0), 2),
                "b": round(point.get("bass", 0), 2),
                "r": round(point.get("rhythm", 0), 2),
            })

        tracks_desc = []
        for t in tracks:
            group_cn = {"melody": "旋律", "harmony": "和声", "bass": "低音", "rhythm": "节奏"}.get(t["group"], t["group"])
            tracks_desc.append(
                f"- ID{t['id']}: {t['name']}（{t['instrument']}，{group_cn}组，{t['note_count']}个音符）"
            )

        user_msg = f"""## 歌曲信息
总时长：{total_seconds:.1f} 秒
轨道数：{len(tracks)}

## 轨道列表
{chr(10).join(tracks_desc)}

## 活跃度曲线（每2秒采样，m=旋律 h=和声 b=低音 r=节奏，0-1越高越活跃）
{json.dumps(compressed, ensure_ascii=False)}

请分析这首歌曲的结构，设计镜头脚本、弹幕、字幕提示。
注意克制原则，不要频繁切换镜头，但也不能太单调。"""

        result = self._call_api(SCRIPT_SYSTEM_PROMPT, user_msg)

        if not result:
            return {
                "sections": [{"start": 0, "end": total_seconds, "name": "全曲", "mood": ""}],
                "cameras": [{"time": 0, "type": "wide", "focus": "all", "duration": total_seconds}],
                "danmaku": [],
                "subtitles": [],
            }

        script = {
            "sections": result.get("sections", []),
            "cameras": result.get("cameras", []),
            "danmaku": result.get("danmaku", []),
            "subtitles": result.get("subtitles", []),
        }

        cache[cache_key] = script
        self._save_cache(cache, SCRIPT_CACHE_FILE)
        return script
